 using namespace boundary;using V=BoundaryValue;auto dynamic=obj({{"id",V{StableId{"control"}}},{"meeting_kind",V{StableId{"born_personal_template"}}},{"template_id",V{StableId{"born_talk"}}},{"accept_node_id",V{StableId{"accept"}}},{"revoke_node_id",V{StableId{"withdraw"}}},{"terms_version",V{Integer{1}}},{"scope",V{StableId{"own_life_control_only"}}}});auto config=obj({{"version",V{Integer{1}}},{"profile",V{StableId{"biological_posthumous_control_v1"}}},{"requests",V{V::Array{dynamic}}}});auto parsed=decode_biological_control_catalog(config);check(parsed.ok,"strict dynamic template policy decode");
