 BiologicalControlTemplateRead templates=[](const StableId& id)->Outcome<BiologicalControlTemplateIdentity>{return {true,{id,"prototype","dialogue"},{}};};check(validate_biological_control_catalog(parsed.value,original,common,interactions,templates).ok,"selected real template binding rejected");check(!validate_biological_control_catalog(parsed.value,original,common,interactions).ok,"missing template source accepted");
