 auto bad=config;bad.find("requests")->as<V::Array>()->front().as<V::Dict>()->emplace_back("successor_actor_id",V{StableId{"prototype"}});check(!decode_biological_control_catalog(bad).ok,"dynamic and Installed binding fields mixed");bad=config;*bad.find("requests")->as<V::Array>()->front().find("scope")=V{StableId{"private_assets"}};check(!decode_biological_control_catalog(bad).ok,"private property authority added to control");
 bad=config;bad.find("requests")->as<V::Array>()->front().as<V::Dict>()->emplace_back("template_id",V{StableId{"other"}});check(!decode_biological_control_catalog(bad).ok,"duplicate template hidden");
