 auto installed=parsed.value;auto* fixed=installed.definitions.find("control");fixed->meeting_kind=BiologicalControlMeetingKind::installed_candidate;fixed->template_id.clear();fixed->predecessor_actor_id="parent";fixed->successor_actor_id="child";fixed->dialogue_id="dialogue";RoleDefinition role;role.id="person";common.roles.insert(role.id,role);interactions.dialogues[0].context_role="person";interactions.dialogues[0].nodes[0].speaker="child";
 check(validate_biological_control_catalog(installed,original,common,interactions).ok,"original exact candidate speaker rejected");fixed->successor_actor_id="actor:future";check(!validate_biological_control_catalog(installed,original,common,interactions).ok,"dynamic actor silently entered Installed selector");
 std::cout<<"BIOLOGICAL_CONTROL_CATALOG "<<checks<<" checks 0 failures\n";return 0;
